M = [
{"id":"kanvermek","yol":["Oruç","Oruç"],"baslik":"Oruçluyken kan vermek veya tahlil için kan aldırmak","ar":"التبرع بالدم للصائم",
 "hanefi":"Hanefî mezhebine göre vücuttan kan çıkması, hacamat ve kan aldırmak orucu bozmaz; çünkü oruç içeriye bir şeyin girmesiyle bozulur, çıkmasıyla bozulmaz. Ancak kişiyi orucu sürdüremeyecek kadar zayıf düşürecekse mekruhtur; bu durumda kan bağışını iftardan sonraya bırakmak uygundur.",
 "mez":{"maliki":["Bozmaz","Zayıf düşürme ihtimali varsa mekruhtur."],
        "safii":["Bozmaz","Zayıflatıyorsa mekruhtur."],
        "hanbeli":["Hacamat bozar","Hanbelîlere göre hacamat yaptırmak ve yapmak orucu bozar; kan bağışını da buna kıyas edenler vardır."]},
 "sebep":"“Hacamat yapan da yaptıran da orucunu bozdu” hadisi ile Hz. Peygamber’in oruçluyken hacamat yaptırdığını bildiren hadis arasındaki çelişki ve neshin varlığı.",
 "delil":[["hadis","Hz. Peygamber’in oruçluyken hacamat olması",hadis("احتجم وهو صائم"),"Buhârî, Savm, 32."],
          ["hadis","“Hacamat yapan da yaptıran da orucunu bozdu.”",hadis("أفطر الحاجم والمحجوم"),"Ebû Dâvûd, Savm, 28; Tirmizî, Savm, 59."]],
 "usul":"Hanefîler, Hz. Peygamber’in sonraki fiilini (Veda Haccı yılındaki hacamat) önceki sözün nâsihi kabul eder; Hanbelîler ise sözü fiile tercih eder."},
{"id":"adetgeciktiren","yol":["Tahâret","Gusül ve hayız"],"baslik":"Âdeti geciktiren ilaç kullanmak","ar":"استعمال ما يؤخر الحيض",
 "hanefi":"Kadının hac, umre veya Ramazan orucu gibi ibadetlerini kesintisiz yapabilmek için âdetini geciktiren ilaç kullanması, sağlığına zarar vermemek şartıyla caizdir; doktora danışılmalıdır. İlaç sebebiyle kanama görülmezse kadın temiz sayılır, ibadetleri geçerlidir. Bununla birlikte âdet, Allah’ın kadınlara yazdığı doğal bir hâldir; bu dönemde ibadet edememek bir eksiklik değildir.",
 "mez":{"maliki":["Zarar yoksa caiz","Sağlığa zarar ihtimali varsa mekruhtur."],
        "safii":["Caiz","Zarar vermemek şartıyla caizdir."],
        "hanbeli":["Caiz","İmam Ahmed zararsız ilacı caiz görmüştür."]},
 "sebep":"Esasta ittifak vardır; hüküm zarar bulunup bulunmamasına bağlıdır.",
 "delil":[["hadis","“Bu, Allah’ın Âdemoğlunun kızlarına yazdığı bir şeydir.”",hadis("إن هذا أمر كتبه الله على بنات آدم"),"Buhârî, Hayz, 1; Müslim, Hac, 119."]],
 "usul":"Zarar vermeyen fiillerde aslolan mubahlıktır; “Zarar vermek de zarara zararla karşılık vermek de yoktur.”"},
{"id":"sigara","yol":["Kurban ve av","Yiyecekler"],"baslik":"Sigara içmek","ar":"التدخين",
 "hanefi":"Sigara, tütünün yaygınlaştığı dönemde bazı âlimlerce mubah veya mekruh görülmüştür. Bugün bilimsel olarak bağımlılık yaptığı, sağlığa ciddi zarar verdiği ve başkalarını da etkilediği kesinleştiğinden Diyanet İşleri Başkanlığı Din İşleri Yüksek Kurulu dahil günümüz âlimlerinin çoğunluğu sigara içmeyi haram görmektedir. Sigara içmek orucu bozar; kişi bilerek içerse kazâ ve keffâret gerekir. Camilerde ve ibadet yerlerinde cemaati rahatsız etmek ayrıca kul hakkıdır.",
 "mez":{"maliki":["Günümüzde haram (çoğunluk)","Eski âlimler arasında ihtilaf vardı."],
        "safii":["Günümüzde haram (çoğunluk)","Zararın kesinleşmesiyle hüküm değişmiştir."],
        "hanbeli":["Günümüzde haram (çoğunluk)","Zarar ve israf illetiyle haram görülür."]},
 "sebep":"Hükmün dayanağı olan zararın kesinleşip kesinleşmediği; eski fetvaların zararın bilinmediği döneme ait olması.",
 "delil":[["ayet","Bakara 2:195","./#2-195","“…Kendinizi kendi ellerinizle tehlikeye atmayın.”"],
          ["ayet","A‘râf 7:157","./#7-157","“…Onlara temiz şeyleri helal, kötü (habâis) şeyleri haram kılar.”"],
          ["hadis","“Zarar vermek de zarara zararla karşılık vermek de yoktur.”",hadis("لا ضرر ولا ضرار"),"İbn Mâce, Ahkâm, 17; Muvatta’, Akdiye, 31."]],
 "usul":"Hüküm illetle birlikte döner: zarar illeti kesinleşince hüküm mubahlıktan haramlığa döner."},
{"id":"kurbanborc","yol":["Kurban ve av","Kurban"],"baslik":"Borçlu kişinin kurban kesmesi","ar":"الأضحية لمن عليه دين",
 "hanefi":"Kurban, Kurban Bayramı günlerinde aslî ihtiyaçlarından ve borcundan başka nisap miktarı mala sahip olan Müslümana vaciptir. Borcu düşüldükten sonra nisaba ulaşan malı bulunmayan kişiye kurban vacip değildir. Böyle biri kurban keserse nafile olarak sevabını alır; ancak borcunu vaktinde ödeyemeyecekse alacaklının hakkını öncelemesi gerekir. Kurban için malın üzerinden bir yıl geçmesi şart değildir.",
 "mez":{"maliki":["Sünnet-i müekkede","Kurban parasına muhtaç olmayan kişi için sünnettir."],
        "safii":["Sünnet-i müekkede","Bayram günlerinde kendisinin ve ailesinin ihtiyacından fazlası olana sünnettir."],
        "hanbeli":["Sünnet-i müekkede","Borçlunun önce borcunu ödemesi evladır."]},
 "sebep":"Kurbanın vacip mi sünnet mi olduğu ve zenginliğin ölçüsü.",
 "delil":[["hadis","“Gücü yettiği hâlde kurban kesmeyen namazgâhımıza yaklaşmasın.”",hadis("من كان له سعة ولم يضح فلا يقربن مصلانا"),"İbn Mâce, Edâhî, 2; Ahmed, Müsned, II, 321."],
          ["ayet","Kevser 108:2","./#108-2","“O hâlde Rabbin için namaz kıl ve kurban kes.”"]],
 "usul":"Hanefîler kurbanı vacip sayar; vücûbun şartı zenginliktir (nisap). Borç, nisabın ölçülmesinde düşülür."},
{"id":"hacborc","yol":["Hac","Hac"],"baslik":"Borçlu kişinin hacca gitmesi","ar":"حج المدين",
 "hanefi":"Hac, yol masrafına ve geri dönünceye kadar ailesinin nafakasına gücü yeten Müslümana farzdır. Borcu olan kişi, önce borcunu ödemekle yükümlüdür; borcunu ödedikten sonra haccın masraflarına gücü yetmiyorsa ona hac farz değildir. Vadesi uzun ve ödemesi güvence altındaki borçlar (taksitli konut kredisi gibi) için alacaklının rızası ve ödeme planı dikkate alınır. Borçlu kişi alacaklısının izniyle hacca gidebilir ve haccı geçerlidir.",
 "mez":{"maliki":["Benzer","Borcu ödemeye yetecek malı hacca harcaması caiz değildir."],
        "safii":["Benzer","Vadesi gelmiş borç öncelikli; vadeli borçta da önce borç hesaba katılır."],
        "hanbeli":["Benzer","Borç istitaatı (güç yetirmeyi) ortadan kaldırır."]},
 "sebep":"“Yol bulabilene” (istitaat) şartının borcu kapsayıp kapsamadığı; kul hakkının Allah hakkına önceliği.",
 "delil":[["ayet","Âl-i İmrân 3:97","./#3-97","“…O’na bir yol bulabilenlerin (gücü yetenlerin) Beyt’i haccetmesi, Allah’ın insanlar üzerindeki hakkıdır.”"],
          ["hadis","Borcun şehide bile affedilmemesi",hadis("يغفر للشهيد كل ذنب إلا الدين"),"Müslim, İmâre, 119."]],
 "usul":"Kul hakkı ile Allah hakkı çatıştığında kul hakkı öncelenir; borç, haccın şartı olan istitaatı ortadan kaldırır."},
]
